function toiletSlowPronunciationMarkup(value=''){
  const safe=esc(String(value||''));
  return safe.replace(/(^|[^A-Za-zÀ-ÖØ-öø-ÿ])([A-Z]{2,})(?=$|[^A-Za-zÀ-ÖØ-öø-ÿ])/g,'$1<b>$2</b>');
}

