function loadState(){
  let raw='';
  try{
    raw=localStorage.getItem(STORAGE_KEY);
    if(!raw){for(const key of LEGACY_STORAGE_KEYS){raw=localStorage.getItem(key);if(raw)break;}}
  }catch(error){
    startupStorageIssueKind='unavailable';
    startupStorageIssue='Local app storage could not be read at launch. Restore a backup or reset local data before saving.';
    console.error('Travel Command Centre local storage read failure:',error);
    return SIMULATION_BUILD?hydrate(demoReviewState()):hydrate(null);
  }
  if(!raw)return SIMULATION_BUILD?hydrate(demoReviewState()):hydrate(null);
  try{const parsed=JSON.parse(raw);startupParsedState=parsed;return hydrate(parsed);}
  catch(error){
    startupStorageIssueKind='corrupt';
    startupStorageIssue='Saved local app data could not be read safely. Restore a backup or reset local data before saving.';
    console.error('Travel Command Centre saved data recovery failure:',error);
    return hydrate(null);
  }
}
