function currentStayExpenses(){ const entry=currentItinerarySegment();if(!entry)return [];if(entry.coverageType==='Intentional Gap')return expenseHistoryRows(state.expenses.filter(x=>between(x.date,entry.arrival,entry.departure)&&!itineraryDestinationForBudgetDate(x.date)));return expenseHistoryRows(state.expenses.filter(x=>recordBelongsToItinerary(x,entry,'expense'))); }
