  const committed=state.expenses.filter(x=>inBudgetYear(x.date)&&parseDate(x.date)?.getMonth()===month).reduce((sum,x)=>sum+Number(x.amount||0)*Number(x.rate||1),0)+linkedReservations().filter(x=>{const d=reservationEffectiveBudgetDate(x);return inBudgetYear(d)&&parseDate(d)?.getMonth()===month;}).reduce((sum,x)=>sum+reservationAudValue(x),0);
