  const reference=itineraryReferenceDate(),ownedStart=itineraryFirstOwnedDateAfter(entry,state.itinerary,reference),start=ownedStart||entry.arrival;
  const interrupted=itineraryEntryHasIntentionalGapOverlay(entry,state.itinerary),ownedSegment=interrupted?itineraryOwnedSegmentsForEntry(entry,state.itinerary).find(segment=>segment.start===start):null,end=ownedSegment?.end||entry.departure;
