function selectedMapJourneys(){
  const routes=[...completedJourneys()].filter(x=>journeyYearsTouched(x.start,x.end).length).sort((a,b)=>String(a.start||'').localeCompare(String(b.start||'')));
  const modeFiltered=mapModeFilters.has('All')||!mapModeFilters.size?routes:routes.filter(x=>mapModeFilters.has(normalizedTravelMode(x.type)));
  if(mapYearFilters.has('All')||!mapYearFilters.size) return modeFiltered;
  const selectedYears=[...mapYearFilters].map(Number).filter(Number.isInteger);
  return modeFiltered.filter(x=>selectedYears.some(year=>rangeOverlapsJourneyYear(x.start,x.end,year)));
}
function geoKey(value){ const source=String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[–—]/g,'-');return source.replace(/[^\p{L}\p{N}, ]+/gu,' ').replace(/\s+/g,' ').trim(); }
function legacyGeoKeyV1(value){ return String(value||'').toLowerCase().replace(/[–—]/g,'-').replace(/[^a-z0-9, ]/g,' ').replace(/\s+/g,' ').trim(); }

// Batches 418–441: country hints for atlas place names that also exist in another
// state/province. A region-qualified label may reuse the base atlas coordinate only when
// the atlas place belongs to the same country as the qualifier; otherwise it must remain
