  const tools=fullPage?`<div class="map-tools"><button type="button" data-map-zoom="out" aria-label="Zoom out">−</button><button type="button" data-map-zoom="reset" aria-label="Fit journey map to visible routes">FIT ROUTE</button><button type="button" data-map-zoom="in" aria-label="Zoom in">＋</button>${readOnly?'':`<button type="button" data-map-edit class="${mapEditMode?'active':''}">${mapEditMode?'Finish Route Editing':'Edit Route Points'}</button><button type="button" data-map-reset-points ${routes.some(x=>Boolean(storedMapPoint(x))||normalizeDetailedRoutePoints(x.routePoints).some(p=>Boolean(storedMapPoint(p))))?'':'disabled'}>Reset Points</button>`}</div>`:`<div class="map-tools map-tools-embedded"><button type="button" data-map-expand class="primary">EXPAND MAP</button></div>`;
  const emptyHeight=large?452:(compact?356:300);
