  if(!mapPanTouched&&rawPoints.length){const fit=mapAutoFitView(rawPoints,{fullPage,kind:'history'});mapZoom=fit.zoom;mapPanX=fit.panX;mapPanY=fit.panY;}
  const points=spreadMapPoints(rawPoints,5.6/Math.max(1,mapZoom),7.3/Math.max(1,mapZoom));
