  const recordedKilometres=routes.reduce((sum,journey)=>sum+Math.max(0,Number(journey.km||0)),0);
  const approximateMappedKilometres=plottedRoutes.slice(1).reduce((sum,x,i)=>sum+(routeKilometres(plottedRoutes[i],x)||0),0);
  const displayedMapKilometres=recordedKilometres||approximateMappedKilometres;
  const displayedMapKilometresLabel=recordedKilometres?'recorded km':'approx. km';
  const selectedYearLabel=mapYearFilters.has('All')?`All ${MAX_JOURNEY_YEARS} travel years`:[...mapYearFilters].map(Number).sort((a,b)=>a-b).map(y=>`Year ${y} · ${journeyYearShortLabel(y)}`).join(', ');
  const activeModes=[routeTypes.stay&&'Flight',routeTypes.motorhome&&'Motorhome',routeTypes.cruise&&'Cruise'].filter(Boolean).join(' · ')||'No routes';
  const historyDenseOverview=!fullPage&&routes.length>14;
