  const yearExpenses=state.expenses.filter(x=>isActualBudgetDate(x.date));
  const catTotals=Object.fromEntries(cats.map(c=>[c,yearExpenses.filter(x=>x.category===c).reduce((sum,x)=>sum+Number(x.amount||0)*Number(x.rate||1),0)]));
  const budgetReference=parseDate(itineraryReferenceDate())||parseDate('2026-01-14');
  const currentMonth=budgetReference.getMonth();
  const monthCatTotals=Object.fromEntries(cats.map(c=>[c,yearExpenses.filter(x=>x.category===c&&parseDate(x.date)?.getMonth()===currentMonth).reduce((sum,x)=>sum+Number(x.amount||0)*Number(x.rate||1),0)]));
  let sortedCats=[...cats].sort((a,b)=>catTotals[b]-catTotals[a]||a.localeCompare(b));
  const max=Math.max(1,...Object.values(catTotals)), reservations=budgetReservationSummaryRows(), filteredExpenses=budgetPeriodExpenses(), reservationSummary=reservationTypeSummary(reservations);
  const totalCats=Object.values(catTotals).reduce((a,b)=>a+b,0);
  const activeDestination=activeDestinationItinerary(),destinationBudgetSet=itineraryBudgetConfigured(activeDestination),currentBudgetSegment=currentItinerarySegment(),plannedTravelDay=currentBudgetSegment?.coverageType==='Intentional Gap';
  const expensePreJourney=!journeyHasStarted();
  const expenseSectionTitle=activeDestination?'2. EXPENSES · TRACK YOUR SPENDING IN LOCAL CURRENCY':plannedTravelDay?'2. EXPENSES · DESTINATION DATE REQUIRED':expensePreJourney?'2. EXPENSES · WAITING FOR DESTINATION DATE':'2. EXPENSES · DESTINATION DATE REQUIRED';
  const expenseContextLabel=activeDestination?'LOCAL CURRENCY':'EXPENSE ROUTING',expenseContextValue=activeDestination?state.currentStay.currency:'DESTINATION ONLY',expenseContextNote=activeDestination?'Saved with this destination':'Choose a date covered by a destination';
  const activeDestinationRouted=itineraryIsRouted(activeDestination),activeDestinationIdentity=activeDestination?routedDepartureIdentity(activeDestination):{city:'',country:''};
  const reservationContextPrefix=plannedTravelDay?'TRAVEL-DAY':activeDestination?(activeDestinationRouted?'CURRENT-TRIP':'CURRENT-STAY'):'CURRENT-DATE';
  const reservationReference=itineraryReferenceDate(),reservationAfterHorizon=journeyPlanningHorizonPassed();
  const reservationContextSubtitle=activeDestination?(activeDestinationRouted?`${journeyHeaderTitle(activeDestination)}${activeDestinationIdentity.country?` · departs ${activeDestinationIdentity.city?`${activeDestinationIdentity.city}, `:''}${activeDestinationIdentity.country}`:''}`:`${state.currentStay.city}${state.currentStay.country?`, ${state.currentStay.country}`:''}`):plannedTravelDay?`${dateFmt(reservationReference)} · planned travel day`:expensePreJourney?`${dateFmt(reservationReference)} · before Journey Start`:reservationAfterHorizon?`${dateFmt(reservationReference)} · outside planning horizon`:`${dateFmt(reservationReference)} · no active stay`;
  const reservationEmptyText=plannedTravelDay?'No reservations for this planned travel day.':activeDestination?(activeDestinationRouted?'No reservations for the current trip.':'No reservations for the current stay.'):'No reservations for this date.';
  const stayBudget=Number(state.currentStay.budget||0), stayRemaining=destinationBudgetSet?stayBudget-local:0, stayPct=destinationBudgetSet?budgetProgress(local,stayBudget):0, actualStayPct=destinationBudgetSet?budgetProgress(actualLocal,stayBudget):0;
  const stayElapsedPct=stayProgress();
  const stayPaceDelta=destinationBudgetSet?actualStayPct-stayElapsedPct:0;
  const paceHealth=destinationBudgetSet?(stayPaceDelta<=5?'green':stayPaceDelta<=15?'amber':'red'):'green';
  const paceHealthLabel=destinationBudgetSet?(paceHealth==='green'?'ON PACE':paceHealth==='amber'?'WATCH':'OVER PACE'):'BUDGET NOT SET';
  const paceHealthWord=destinationBudgetSet?(paceHealth==='green'?'GREEN':paceHealth==='amber'?'AMBER':'RED'):'PAUSED';
  const paceDial=destinationBudgetSet?Math.max(0,Math.min(100,50+(stayPaceDelta*2.5))):0;
