    const phaseRows=phases.map(name=>{const rows=state.checklist.filter(x=>checklistPhaseFor(x)===name&&overviewEligible(x)),done=rows.filter(x=>x.done).length;return {name,total:rows.length,done,pending:rows.length-done};});
