  const valid=state.vault.filter(x=>['Valid','Active'].includes(vaultRecordStatus(x))).length;
  const attachments=state.vault.reduce((sum,x)=>sum+(Array.isArray(x.attachments)?x.attachments.length:0),0);
  const recentOrder=new Map(state.vault.map((record,index)=>[String(record?.id||''),index]));
  const recent=[...state.vault].sort((a,b)=>parseAppDateTimeValue(b.updatedAt||b.addedAt)-parseAppDateTimeValue(a.updatedAt||a.addedAt)||(recentOrder.get(String(b.id||''))??-1)-(recentOrder.get(String(a.id||''))??-1)||String(b.id||'').localeCompare(String(a.id||''))).slice(0,5);
  const countries=vaultCountryFilterOptions();
  if(vaultCountryFilter!=='All'&&!countries.some(value=>slugifyCountry(value)===slugifyCountry(vaultCountryFilter)))countries.push(vaultCountryFilter);
  countries.sort((a,b)=>a.localeCompare(b));
