  const vaultFocusTone={'Passport':'vault-focus-passport','Visa':'vault-focus-visa','Insurance':'vault-focus-insurance','Accommodation details':'vault-focus-accommodation','Emergency contact':'vault-focus-emergency'}[vaultFocusType]||'vault-focus-passport';
  const vaultFocusRows=vaultFocusType?state.vault.filter(x=>x.type===vaultFocusType):[];
  const vaultFocusValid=vaultFocusRows.filter(x=>['Valid','Active'].includes(vaultRecordStatus(x))).length;
  const vaultFocusAttention=vaultFocusRows.filter(x=>vaultRecordNeedsExpiryAttention(x,180)).length;
  const vaultFocusAttachments=vaultFocusRows.reduce((sum,x)=>sum+(Array.isArray(x.attachments)?x.attachments.length:0),0);
  const vaultFocusBody=vaultFocusType?`<div class="vault-focus-summary">${readabilityMetric('Records',vaultFocusRows.length,'saved locally')}${readabilityMetric('Valid / active',vaultFocusValid,'ready to use')}${readabilityMetric('Needs attention',vaultFocusAttention,vaultFocusAttention===1?'record':'records',vaultFocusAttention?'warn':'')}${readabilityMetric('Screenshots',vaultFocusAttachments,'attachments')}</div><div class="vault-focus-actions"><p>${esc(vaultTypeLabel(vaultFocusType))} are shown here in a larger easy-read view. Tap a record to edit it.</p><button data-vault-show-list="${esc(vaultFocusType)}">SHOW ${esc(vaultTypeLabel(vaultFocusType).toUpperCase())} IN MAIN LIST</button></div><div class="vault-focus-list">${vaultFocusRows.map(record=>{const status=vaultRecordStatus(record),count=Array.isArray(record.attachments)?record.attachments.length:0,subtype=record.type==='Passport'&&record.identityKind&&record.identityKind!=='Passport'?record.identityKind:record.type==='Insurance'&&record.insuranceProvider?record.insuranceProvider:record.type==='Visa'&&record.visaEntries?`${record.visaEntries} entry`:vaultTypeLabel(record.type),detail=[record.country,subtype,record.reference].filter(Boolean).join(' · ');return `<article class="vault-focus-row" data-edit-row="vault:${record.id}" tabindex="0" role="button" aria-label="Edit Vault record ${esc(record.name)}"><span class="vault-focus-row-icon">${vaultSectionIcon(record.type)}</span><span class="vault-focus-row-copy"><b>${esc(record.name)}</b><small>${esc(detail||record.notes||'No additional details')}</small><em>${esc(record.owner||'Shared')} · ${record.expiry?`Valid until ${dateFmt(record.expiry)}`:'No expiry date'}</em></span><strong><i class="vault-status-pill ${status.toLowerCase().replaceAll(' ','-')}">${esc(status)}</i><small>${count} screenshot${count===1?'':'s'}</small></strong></article>`}).join('')||empty(`No ${vaultTypeLabel(vaultFocusType).toLowerCase()} saved yet.`)}</div>`:'';
  const vaultFocusOverlay=vaultStreamingOpen?'':(vaultFocusType?readabilityFocusOverlay('vault',vaultTypeLabel(vaultFocusType).toUpperCase(),vaultFocusBody,vaultFocusTone,'Vault category views are read-only summaries. Tap a record to edit it, or show the category in the main list.'):'');
  return `${cinematicHero('vault')}<div class="vault-access-region ${vaultUnlocked?'is-unlocked':'is-locked'}"><div class="vault-access-shell" ${vaultUnlocked?'':'inert aria-hidden="true"'}><div class="vault-screen-grid vault-screen-stack"><main>
    <div class="vault-category-grid">${types.map(type=>{const rows=state.vault.filter(x=>x.type===type);const active=vaultTypeFilter===type;const tone={'Passport':'vault-passport','Visa':'vault-visa','Insurance':'vault-insurance','Accommodation details':'vault-accommodation','Emergency contact':'vault-emergency'}[type]||'vault-passport';const focus={'Passport':'passport','Visa':'visa','Insurance':'insurance','Accommodation details':'accommodation','Emergency contact':'emergency'}[type];return `<button class="vault-category ${tone} ${active?'active':''}" data-vault-focus="${focus}" aria-label="Open ${esc(vaultTypeLabel(type))} in expanded view"><span>${vaultSectionIcon(type)}</span><b>${esc(vaultTypeLabel(type))}</b><strong>${rows.length}</strong><small>${rows.length===1?'record':'records'}</small></button>`}).join('')}</div>
    <section class="vault-records-collapse ${vaultRecordsExpanded?'is-open':''}" aria-label="All Vault records">
      <button class="vault-records-toggle" type="button" data-vault-records-toggle aria-expanded="${vaultRecordsExpanded?'true':'false'}" aria-controls="vault-records-collapse-body">
        <span class="vault-records-toggle-icon">${iconMarkup('vault','vault-records-toggle-mark')}</span>
        <span class="vault-records-toggle-copy"><b>ALL VAULT RECORDS</b><small>${state.vault.length} record${state.vault.length===1?'':'s'} · ${attachments} screenshot attachment${attachments===1?'':'s'}</small></span>
        <span class="vault-records-toggle-action">${vaultRecordsExpanded?'CLOSE':'OPEN'} <i aria-hidden="true">${vaultRecordsExpanded?'▴':'▾'}</i></span>
      </button>
      ${vaultRecordsExpanded?`<div class="vault-records-collapse-body" id="vault-records-collapse-body">
        <section class="vault-records-card vault-filter-card">
          <div class="vault-filterbar"><label class="vault-search approved-search-field">${iconMarkup('search','search-field-icon')}<input id="vault-search" aria-label="Search Vault records" value="${esc(vaultSearchQuery)}" placeholder="Search name, owner, country, reference or notes"></label><select id="vault-type-filter" aria-label="Filter Vault records by section"><option value="All">All sections</option>${types.map(x=>`<option value="${esc(x)}" ${vaultTypeFilter===x?'selected':''}>${esc(vaultTypeLabel(x))}</option>`).join('')}</select><select id="vault-owner-filter" aria-label="Filter Vault records by owner"><option value="All">All owners</option>${['Cameron','Kym','Shared'].map(x=>`<option value="${x}" ${vaultOwnerFilter===x?'selected':''}>${x}</option>`).join('')}</select><select id="vault-country-filter" aria-label="Filter Vault records by country"><option value="All">All countries</option>${countries.map(x=>`<option value="${esc(x)}" ${vaultCountryFilter!=='All'&&slugifyCountry(vaultCountryFilter)===slugifyCountry(x)?'selected':''}>${esc(x)}</option>`).join('')}</select><button id="clear-vault-filters">Clear</button><button class="primary vault-add-document" data-add="vault">＋ ADD DOCUMENT</button></div>
        </section>
        <section class="vault-records-section" aria-label="Vault records">
          <div class="vault-table-heading"><div><h3>${recordsHeading}</h3><span><b id="vault-shown-count">${filtered.length}</b> shown · ${attachments} screenshot attachment${attachments===1?'':'s'}</span></div><span class="local-only">${iconMarkup('vault','local-only-icon')}<span>LOCAL ONLY</span></span></div>
          <div id="vault-table">${vaultTable(filtered)}</div>
        </section>
        <p class="vault-local-note">${iconMarkup('vault','local-note-icon')}<span>All records and screenshot attachments are stored locally on this device. No Vault data is sent to the cloud.</span></p>
      </div>`:''}
    </section>
  </main>
  <section class="vault-lower-grid" aria-label="Vault summary and checks">
    ${card('DOCUMENT SUMMARY',`<div class="vault-summary-grid"><div><span>${iconMarkup('vault','vault-summary-icon')}</span><b>${state.vault.length}</b><small>Total records</small></div><div><span>${iconMarkup('checklist','vault-summary-icon')}</span><b>${valid}</b><small>Valid / active</small></div><div class="warn"><span>${iconMarkup('calendar','vault-summary-icon')}</span><b>${expiring.length}</b><small>Expiry watch · 180d</small></div><div class="danger"><span>${iconMarkup('delete','vault-summary-icon')}</span><b>${expired}</b><small>Expired</small></div></div>`,'vault-side-summary')}
    ${card('EXPIRY REMINDERS',expiryReminderRows.length?expiryReminderRows.slice(0,6).map(x=>{const isExpired=x._days<0,band=isExpired?'expiry-30':x._days<=30?'expiry-30':x._days<=90?'expiry-90':'expiry-180',lead=isExpired?'EXPIRED':x._days===0?'TODAY':x._days<=30?'30-DAY WATCH':x._days<=90?'90-DAY WATCH':'180-DAY WATCH';return `<button class="vault-reminder ${band}" data-edit="vault:${x.id}"><span class="vault-mini-icon">${vaultSectionIcon(x.type)}</span><div><b>${esc(x.name)}</b><small>${isExpired?'Expired':'Expires'} ${dateFmt(x.expiry)}</small></div><em><strong>${lead}</strong><span>${isExpired?`${dayCountLabel(Math.abs(x._days))} ago`:x._days===0?'Today':dayCountLabel(x._days)}</span></em></button>`}).join(''):empty('No expired records or records expiring within 180 days.'),'vault-side-expiry')}
    ${card('EMERGENCY TRAVEL CARD',`<div class="vault-emergency-travel-card"><div class="vault-emergency-country"><small>${emergencyCard.active?'CURRENT COUNTRY':'DESTINATION STATUS'}</small><b>${esc(emergencyCard.country)}</b></div><div class="vault-emergency-line"><span>LOCAL EMERGENCY</span>${emergencyCard.local?`<button data-edit="vault:${emergencyCard.local.id}"><b>${esc(emergencyCard.local.name)}</b><small>${esc(vaultEmergencyPrimaryDetail(emergencyCard.local))}</small></button>`:`<em>Not saved in Vault</em>`}</div><div class="vault-emergency-line"><span>AUSTRALIAN EMBASSY / CONSULATE</span>${emergencyCard.embassy?`<button data-edit="vault:${emergencyCard.embassy.id}"><b>${esc(emergencyCard.embassy.name)}</b><small>${esc(vaultEmergencyPrimaryDetail(emergencyCard.embassy))}</small></button>`:`<em>Not saved in Vault</em>`}</div><div class="vault-emergency-line"><span>INSURANCE ASSISTANCE</span>${emergencyCard.insurance?`<button data-edit="vault:${emergencyCard.insurance.id}"><b>${esc(emergencyCard.insurance.insuranceProvider||emergencyCard.insurance.name)}</b><small>${esc(emergencyCard.insurance.assistancePhone||'Assistance number not saved')}</small></button>`:`<em>${emergencyCard.insuranceSaved?'No current cover for this destination':'No insurance record saved'}</em>`}</div><small class="vault-emergency-note">Tap any contact to open the full saved record.</small></div>`,'vault-side-emergency-travel')}
    ${card('EMERGENCY CONTACTS',emergency.length?emergency.slice(0,4).map(x=>{const info=vaultEmergencyContactDisplay(x);return `<button class="emergency-contact emergency-contact-readable" data-edit="vault:${x.id}"><span class="emergency-cross">+</span><div class="emergency-contact-copy"><b>${esc(x.name)}</b><small>${esc(info.meta||'Shared')}</small><strong>${esc(info.primary)}</strong>${info.notes?`<em>${esc(info.notes)}</em>`:''}</div></button>`}).join(''):empty('No emergency contacts saved.'),'vault-side-emergency')}
    ${card('RECENT ACTIVITY',recent.length?recent.map(x=>`<button class="vault-activity" data-edit="vault:${x.id}"><span class="vault-mini-icon">${vaultSectionIcon(x.type)}</span><div><b>${esc(x.name)}</b><small>${esc(x.lastAction||'Saved')} · ${esc(x.owner||'')}</small></div><time>${esc(x.updatedAt||x.addedAt||'')}</time></button>`).join(''):empty('No Vault activity yet.'),'vault-side-activity')}
  </section>
  </div></div>${vaultUnlocked?'':`<div class="vault-access-veil" aria-label="Vault locked"><div class="vault-access-locked-badge"><span>${iconMarkup('vault','vault-lock-badge-icon')}</span><b>VAULT LOCKED</b><small>Protected access</small></div></div>`}</div>${vaultUnlocked?vaultFocusOverlay:''}${vaultUnlocked&&vaultStreamingOpen?vaultStreamingOverlay():''}${vaultUnlocked&&vaultStreamingEmailOpen&&!vaultStreamingOpen?vaultStreamingEmailOverlay():''}`;
