function vaultTable(list){
  if(!list.length) return `<div class="vault-record-list vault-record-empty">${empty('No Vault records match these filters.')}</div>`;
  return `<div class="vault-record-list">${list.map(record=>{
    const status=vaultRecordStatus(record);
    const count=Array.isArray(record.attachments)?record.attachments.length:0;
    const subtype=record.type==='Passport'&&record.identityKind&&record.identityKind!=='Passport'?record.identityKind:record.type==='Insurance'&&record.insuranceProvider?record.insuranceProvider:record.type==='Visa'&&record.visaEntries?`${record.visaEntries} entry`:vaultTypeLabel(record.type);
    const details=[record.country,subtype,record.reference].filter(Boolean).join(' · ');
    const tone={'Passport':'vault-record-passport','Visa':'vault-record-visa','Insurance':'vault-record-insurance','Accommodation details':'vault-record-accommodation','Emergency contact':'vault-record-emergency'}[record.type]||'vault-record-default';
    const statusClass=status.toLowerCase().replaceAll(' ','-');
    const screenshots=count?`<button class="vault-attachment-button vault-record-attachment" data-vault-attachments="${record.id}" aria-label="Open ${count} screenshot attachment${count===1?'':'s'} for ${esc(record.name)}">${iconMarkup('vault','attachment-icon')}<span>${count}</span></button>`:`<span class="vault-attachment-zero" aria-label="No screenshot attachments for ${esc(record.name)}">0</span>`;
    return `<article class="vault-record-card ${tone}" data-edit-row="vault:${record.id}" tabindex="0" role="button" aria-label="Edit Vault record ${esc(record.name)}">
      <div class="vault-record-head"><span class="vault-record-icon">${vaultSectionIcon(record.type)}</span><div class="vault-record-title"><b>${esc(record.name)}</b><small>${esc(details||record.notes||'')}</small></div></div>
      <div class="vault-record-fields">
        <div class="vault-record-field"><span>OWNER</span><strong>${esc(record.owner||'—')}</strong></div>
        <div class="vault-record-field"><span>EXPIRY / VALID UNTIL</span><strong>${dateFmt(record.expiry)}</strong></div>
        <div class="vault-record-field"><span>STATUS</span><strong><em class="vault-status-pill ${statusClass}">${esc(status)}</em></strong></div>
        <div class="vault-record-field vault-record-screenshots"><span>SCREENSHOTS</span><strong>${screenshots}</strong></div>
        <div class="vault-record-field vault-record-actions"><span>ACTIONS</span><strong>${actions('vault',record.id)}</strong></div>
      </div>
    </article>`;
  }).join('')}</div>`;
}


function serviceWorkerSupportAvailable(){return typeof navigator==='object'&&Boolean(navigator.serviceWorker)&&typeof navigator.serviceWorker.register==='function';}
function serviceWorkerControllerVersionIssue(){
  if(!serviceWorkerSupportAvailable()||!navigator.serviceWorker.controller)return '';
  const scriptUrl=String(navigator.serviceWorker.controller.scriptURL||''),version=new URLSearchParams(scriptUrl.split('?')[1]||'').get('v');
  return version===APP_SHELL_REVISION?'':'Offline Service Worker is not on the current app shell revision.';
}
function serviceWorkerStatusSummary(){
  if(!serviceWorkerSupportAvailable())return {label:'Unavailable',sidebar:'Offline unavailable',tone:'danger',issue:'Offline Service Worker support is unavailable.'};
  if(serviceWorkerRegistrationError)return {label:'Setup failed',sidebar:'Offline setup failed',tone:'danger',issue:serviceWorkerRegistrationError};
  const versionIssue=serviceWorkerControllerVersionIssue();
  if(versionIssue)return {label:'Update needed',sidebar:'Offline update needed',tone:'warning',issue:versionIssue};
  if(!navigator.serviceWorker.controller){
    if(serviceWorkerRegistrationPending)return {label:'Starting',sidebar:'Offline starting',tone:'warning',issue:'Offline Service Worker is not controlling this page yet.'};
    return {label:'Restart needed',sidebar:'Offline restart needed',tone:'warning',issue:'Offline Service Worker is not controlling this page yet. Close and reopen the app.'};
  }
  return {label:'Ready',sidebar:'Offline ready',tone:'success',issue:''};
}
function registerOfflineServiceWorker(){
  serviceWorkerRegistrationError='';serviceWorkerRegistrationPending=false;
  if(!serviceWorkerSupportAvailable()){updateDataStatus();return;}
  serviceWorkerRegistrationPending=true;updateDataStatus();
  try{
    Promise.resolve(navigator.serviceWorker.register(`./sw.js?v=${encodeURIComponent(APP_SHELL_REVISION)}`,{updateViaCache:'none'})).then(()=>{serviceWorkerRegistrationPending=false;serviceWorkerRegistrationError='';updateDataStatus();scheduleScreenRefresh('offline');}).catch(error=>{serviceWorkerRegistrationPending=false;serviceWorkerRegistrationError='Offline Service Worker setup failed. Close and reopen the app; if this remains, reinstall the offline app.';console.error('Travel Command Centre Service Worker registration:',error);updateDataStatus();scheduleScreenRefresh('offline');});
  }catch(error){serviceWorkerRegistrationPending=false;serviceWorkerRegistrationError='Offline Service Worker setup failed. Close and reopen the app; if this remains, reinstall the offline app.';console.error('Travel Command Centre Service Worker registration:',error);updateDataStatus();scheduleScreenRefresh('offline');}
}
function runtimeAssetVersionIssues(){
  const nodes=[...document.querySelectorAll('script[src],link[href]')],urls=nodes.map(node=>node.getAttribute('src')||node.getAttribute('href')||'').filter(Boolean),required=['app.js','styles.css','manifest.webmanifest'],issues=[];
  required.forEach(name=>{const matches=urls.filter(url=>String(url).split('?')[0].split('/').pop()===name);if(!matches.length){issues.push(`${name} is not linked by the current app shell.`);return;}if(matches.some(url=>new URLSearchParams(String(url).split('?')[1]||'').get('v')!==APP_SHELL_REVISION))issues.push(`${name} is not linked to the current app version.`);});
  return issues;
}

