const finishExpandedPointerPan=event=>{if(expandedPointerPan?.id===event.pointerId){expandedPointerPan=null;queueMicrotask(()=>refreshForDeviceClock());}};
document.addEventListener('pointerup',finishExpandedPointerPan);
document.addEventListener('pointercancel',finishExpandedPointerPan);
